  if(action==='complete-flex-position'){let finished=false,id=state.flexibility.active?.id;if(!await mutate(s=>{finished=completeFlexibilityPosition(s);})){return;}lastFlexTargetPositive=false;if(finished){flexCompleted=id;screen='flex-finish';}}
  if(action==='confirm-abandon-flex'){openPanel(`<h2>Routine en cours</h2><p>Les positions déjà terminées resteront dans l’historique si tu arrêtes.</p>${button('Continuer la routine','close-panel','primary full')}${button('Arrêter la routine','abandon-flex','secondary full danger')}`,{size:'small',label:'Pause ou arrêt de la routine'});return;}
  if(action==='abandon-flex'){if(!await mutate(s=>abandonFlexibility(s)))return;floatingPanel=null;screen='flexibility';}
