  if(action==='view-current-block'){viewedBlockId=null;render();return;}
  if(action==='skip-block'){const blockId=el.dataset.block;if(!await mutate(s=>skipBlock(s,blockId))){toast('Ce bloc ne peut pas être passé maintenant.');return;}floatingPanel=null;viewedBlockId=null;screen='today';render();return;}
  if(action==='reopen-block'){if(!await mutate(s=>reopenBlock(s,el.dataset.block))){toast('Ce bloc ne peut plus être réouvert.');return;}floatingPanel=null;viewedBlockId=null;screen='today';render();return;}
