  if(action==='select-mode'){selectedModes[el.dataset.id]=el.dataset.mode;render();return;}
  if(action==='feedback'){feedback();return;}if(action==='feedback-last'){feedback({index:state.active.results.length-1});return;}if(action==='edit-result'){feedback({history:el.dataset.history,index:Number(el.dataset.index)});return;}
  if(action.startsWith('export')){const scope=action==='export-all'?'all':action==='export-backup'?'backup':'current';download(exportPayload(db,scope),`muscu-${scope}-${new Date().toISOString().slice(0,10)}.json`);return;}
  if(action==='import'){document.querySelector('#import-file')?.click();return;}
