  if(action==='pause'){if(!await mutate(s=>pause(s)))return;screen='today';floatingPanel=null;render();return;}
  if(action==='resume-now'){if(!await mutate(s=>resume(s)))return;floatingPanel=null;screen='session';}
  if(action==='abandon'){if(!await mutate(s=>abandon(s)))return;floatingPanel=null;viewedBlockId=null;screen='today';}
