  if(action==='skip-suggestion'){if(!await mutate(s=>{restSuggestion(s);return skipSuggestedActivity(s,false);})){return;}}
  if(action==='recover'){if(!await mutate(s=>{restSuggestion(s);return skipSuggestedActivity(s,true);})){return;}}
  if(action==='why-activity'){const suggestion=restSuggestion(state);if(suggestion)openPanel(`<span class="eyebrow">POURQUOI ?</span><h2>${esc(suggestion.item.variantName||suggestion.item.name)}</h2><p>${esc(suggestion.assessment.reason)}</p><p class="subtle">Le chrono de la série principale continue et sa zone finale reste protégée.</p>`,{size:'small',label:'Pourquoi cette activité'});return;}
  if(['level','quick-level'].includes(action)){const delta=Number(el.dataset.delta??1),id=el.dataset.id,mode=el.dataset.mode||'force',activeId=state.active?.id,refreshPanel=action==='level'&&Boolean(floatingPanel);if(!await mutate(s=>changeLevel(s,id,delta,Date.now(),mode))){toast('Ce palier n’est pas disponible pour le moment.');return;}if(activeId&&!state.active){completed=activeId;screen='finish';}render();if(refreshPanel)showExercise(id,mode);return;}
  if(action==='request-phase'){const p=phaseUnlockProgress(state);openPanel(`<span class="eyebrow">${p.ready?'RECOMMANDÉ':'PROGRESSION ANTICIPÉE'}</span><h2>Quand appliquer ${esc(p.label)} ?</h2>${!p.ready?'<p>Le programme conseille encore certains critères. Tu peux néanmoins continuer.</p>':''}${button('Prochain cycle — recommandé','activate-phase','primary full',`data-apply="next" data-force="${!p.ready}"`)}${button('Cycle actuel','activate-phase','secondary full',`data-apply="current" data-force="${!p.ready}"`)}`,{size:'compact',label:'Choix de phase'});return;}
  if(action==='activate-phase'){if(await mutate(s=>unlockPhase(s,Date.now(),{force:el.dataset.force==='true',apply:el.dataset.apply}))){floatingPanel=null;render();}return;}
  if(action==='request-sport-mode'){const p=modeUnlockProgress(state,el.dataset.line,el.dataset.mode),warning=!p?.ready;openPanel(`<span class="eyebrow">${warning?'ACTIVATION ANTICIPÉE':'PRÊT'}</span><h2>Activer ${MODES[el.dataset.mode]}</h2>${warning?`<p class="recommendation ${el.dataset.mode==='power'?'pain':''}">${el.dataset.mode==='power'?'Puissance déconseillée actuellement.':'Les prérequis restent recommandés.'}</p>`:''}${button(warning?'Activer malgré la recommandation':'Activer','activate-sport-mode','primary full',`data-line="${el.dataset.line}" data-mode="${el.dataset.mode}" data-force="${warning}"`)}`,{size:'small',label:'Activation du mode sportif'});return;}
  if(action==='activate-sport-mode'){if(await mutate(s=>unlockMode(s,el.dataset.line,el.dataset.mode,Date.now(),el.dataset.force==='true'))){floatingPanel=null;render();}return;}
  if(action==='apply-objective'){if(await mutate(s=>requestObjectiveChange(s,el.dataset.zone,el.dataset.value,el.dataset.apply))){pendingObjectiveUi=null;render();}return;}
  if(action==='select-profile'){const value=el.dataset.profile;if(value===db.activeProfile||value==='test'&&!db.profiles.test)return;if(await mutate((_s,d)=>switchProfile(d,value))){state=activeState(db);viewedBlockId=null;screen=activeScreen(state);}render();return;}
  if(action==='create-test'||action==='copy-test'){if(await mutate((_s,d)=>createTestProfile(d,action==='copy-test'))){state=activeState(db);floatingPanel=null;viewedBlockId=null;screen='today';}render();return;}
  if(action==='confirm-reset-test'){confirmPanel('Réinitialiser le profil Test','Toutes les données du profil Test seront effacées. Le profil Principal ne change pas.','reset-test','','Réinitialiser');return;}
  if(action==='confirm-reset-principal'){confirmPanel('Réinitialiser le profil Principal','Les données actuelles seront réinitialisées selon l’option choisie.','reset-principal',`data-choice="${el.dataset.choice}"`,'Réinitialiser');return;}
  if(action==='confirm-restore-backup'){confirmPanel('Restaurer la sauvegarde','Le profil Principal actuel sera remplacé par la sauvegarde interne.','restore-backup','','Restaurer');return;}
  if(action==='confirm-delete-backup'){confirmPanel('Supprimer la sauvegarde','Cette sauvegarde interne sera définitivement supprimée.','delete-backup','','Supprimer');return;}
  if(action==='reset-test'){if(await mutate((_s,d)=>resetTest(d))){state=activeState(db);floatingPanel=null;viewedBlockId=null;screen='today';}render();return;}
  if(action==='reset-principal'){if(await mutate((_s,d)=>resetPrincipal(d,el.dataset.choice))){state=activeState(db);floatingPanel=null;viewedBlockId=null;screen='today';}render();return;}
  if(action==='restore-backup'){if(await mutate((_s,d)=>restoreBackup(d))){state=activeState(db);floatingPanel=null;viewedBlockId=null;screen='today';}render();return;}
  if(action==='delete-backup'){if(await mutate((_s,d)=>deleteBackup(d)))floatingPanel=null;render();return;}
  if(action==='update'){if(!state.active&&waitingWorker)waitingWorker.postMessage('ACTIVATE');return;}
  if(action==='history-scope'){historyScope=el.dataset.scope;historyExercise=null;historyFlexExercise=null;render();return;}
  if(action==='history-view'){historyView=el.dataset.view;historyExercise=null;historyFlexExercise=null;render();return;}
  if(action==='history-period'){historyPeriod=el.dataset.period;render();return;}
  if(action==='history-exercise'){historyExercise=el.dataset.id;render();window.scrollTo(0,0);return;}
  if(action==='history-exercise-back'){historyExercise=null;render();return;}
  if(action==='history-flex-exercise'){historyFlexExercise=el.dataset.id;render();window.scrollTo(0,0);return;}
  if(action==='history-flex-back'){historyFlexExercise=null;render();return;}
